-- MARKET POS V2: DEBTS AND SETTLEMENTS
-- Additive coexistence: legacy debt_payments, sales, payments and shifts remain untouched.

-- Permission registry ---------------------------------------------------------
alter table public.permissions disable trigger v2_permissions_prevent_insert;
insert into public.permissions(code,module,description,critical) values
 ('debts.reverse','debts','Reverse a posted customer debt collection.',true),
 ('debts.write_off','debts','Write off and restore customer receivables.',true),
 ('settlements.close','settlements','Close and correct settlement periods.',true)
on conflict(code) do update set module=excluded.module,description=excluded.description,critical=excluded.critical;
alter table public.permissions enable trigger v2_permissions_prevent_insert;

insert into public.permission_profile_permissions(permission_profile_id,permission_id)
select '00000000-0000-0000-0000-000000000101'::uuid,id
from public.permissions where code in('debts.reverse','debts.write_off','settlements.close')
on conflict do nothing;
update public.organization_memberships m set permission_version=permission_version+1
where m.status='active' and exists(
 select 1 from public.membership_permission_profiles x
 where x.membership_id=m.id and x.permission_profile_id='00000000-0000-0000-0000-000000000101'::uuid
);

-- Debt sale compatibility ----------------------------------------------------
alter table public.sales_v2 drop constraint sales_v2_amounts_check;
alter table public.sales_v2 add constraint sales_v2_amounts_check check(
 subtotal_amount>=0 and discount_amount>=0 and tax_amount=0 and total_amount>=0
 and paid_amount>=0 and debt_amount>=0
 and total_amount=subtotal_amount-discount_amount
 and paid_amount+debt_amount=total_amount
 and (debt_amount=0 or customer_counterparty_id is not null)
);
alter table public.sale_returns drop constraint sale_returns_amount_check;
alter table public.sale_returns add constraint sale_returns_amount_check check(total_amount>=0 and debt_reduction_amount>=0 and debt_reduction_amount<=total_amount);
alter table public.sale_return_lines drop constraint sale_return_lines_amount_check;
alter table public.sale_return_lines add constraint sale_return_lines_amount_check check(refund_amount>=0 and debt_reduction_amount>=0 and debt_reduction_amount<=refund_amount);

-- Receivable projection ------------------------------------------------------
create table public.receivables(
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete restrict,
 branch_id uuid not null references public.branches(id) on delete restrict,
 counterparty_id uuid not null references public.counterparties(id) on delete restrict,
 sale_id uuid not null references public.sales_v2(id) on delete restrict,
 original_amount numeric(18,4) not null,
 outstanding_amount numeric(18,4) not null,
 currency_code char(3) not null,
 due_date date,
 status text not null default 'open',
 version bigint not null default 1,
 created_by uuid not null references public.organization_memberships(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,
 created_at timestamptz not null default now(),
 closed_at timestamptz,
 constraint receivables_amount_check check(original_amount>0 and outstanding_amount>=0 and outstanding_amount<=original_amount),
 constraint receivables_currency_check check(currency_code::text~'^[A-Z]{3}$'),
 constraint receivables_status_check check(status in('open','partial','paid','written_off','reversed')),
 constraint receivables_state_check check(
  (status='open' and outstanding_amount=original_amount and closed_at is null) or
  (status='partial' and outstanding_amount>0 and outstanding_amount<original_amount and closed_at is null) or
  (status in('paid','written_off','reversed') and outstanding_amount=0 and closed_at is not null)
 ),
 unique(sale_id),unique(command_id)
);
create index receivables_journal_idx on public.receivables(organization_id,counterparty_id,currency_code,status,due_date,id);
create index receivables_branch_idx on public.receivables(branch_id,status,due_date);
create index receivables_overdue_idx on public.receivables(organization_id,due_date,id) where status in('open','partial');

-- V2 debt payment document ---------------------------------------------------
create table public.debt_payments_v2(
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete restrict,
 branch_id uuid not null references public.branches(id) on delete restrict,
 register_id uuid not null references public.registers(id) on delete restrict,
 counterparty_id uuid not null references public.counterparties(id) on delete restrict,
 shift_id uuid not null references public.shifts_v2(id) on delete restrict,
 document_number text not null,business_date date not null,total_amount numeric(18,4) not null,
 currency_code char(3) not null,status text not null default 'posted',
 device_id uuid not null references public.devices_v2(id) on delete restrict,
 local_operation_id uuid not null,client_created_at timestamptz not null,
 posted_by uuid not null references public.organization_memberships(id) on delete restrict,
 posted_at timestamptz not null default now(),
 reversal_of_id uuid references public.debt_payments_v2(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,
 created_at timestamptz not null default now(),
 constraint debt_payments_v2_number_check check(btrim(document_number)<>''),
 constraint debt_payments_v2_amount_check check(total_amount>0),
 constraint debt_payments_v2_currency_check check(currency_code::text~'^[A-Z]{3}$'),
 constraint debt_payments_v2_status_check check(status in('posted','reversed')),
 unique(organization_id,document_number),unique(organization_id,device_id,local_operation_id),unique(command_id)
);
create unique index debt_payments_v2_one_reversal on public.debt_payments_v2(reversal_of_id) where reversal_of_id is not null;
create index debt_payments_v2_journal_idx on public.debt_payments_v2(organization_id,counterparty_id,business_date desc,id);
create index debt_payments_v2_shift_idx on public.debt_payments_v2(shift_id,posted_at);

alter table public.payments_v2 add column debt_payment_id uuid references public.debt_payments_v2(id) on delete restrict;
alter table public.payments_v2 drop constraint payments_v2_source_check;
alter table public.payments_v2 add constraint payments_v2_source_check check(
 (sale_id is not null)::integer+(sale_return_id is not null)::integer+(debt_payment_id is not null)::integer=1
);
create index payments_v2_debt_payment_idx on public.payments_v2(debt_payment_id) where debt_payment_id is not null;

-- Signed append-only debt allocations ---------------------------------------
create table public.debt_allocations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 receivable_id uuid not null references public.receivables(id) on delete restrict,
 debt_payment_id uuid references public.debt_payments_v2(id) on delete restrict,
 sale_return_id uuid references public.sale_returns(id) on delete restrict,
 sale_reversal_id uuid references public.sales_v2(id) on delete restrict,
 allocation_type text not null,amount numeric(18,4) not null,
 reversal_of_id uuid references public.debt_allocations(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,
 approval_request_id uuid references public.approval_requests(id) on delete restrict,
 created_by uuid not null references public.organization_memberships(id) on delete restrict,
 created_at timestamptz not null default now(),
 constraint debt_allocations_type_check check(allocation_type in('payment','return','write_off','sale_reversal')),
 constraint debt_allocations_source_check check(
  (allocation_type='payment' and debt_payment_id is not null and sale_return_id is null and sale_reversal_id is null) or
  (allocation_type='return' and sale_return_id is not null and debt_payment_id is null and sale_reversal_id is null) or
  (allocation_type='write_off' and debt_payment_id is null and sale_return_id is null and sale_reversal_id is null and approval_request_id is not null) or
  (allocation_type='sale_reversal' and sale_reversal_id is not null and debt_payment_id is null and sale_return_id is null)
 ),
 constraint debt_allocations_sign_check check((reversal_of_id is null and amount>0)or(reversal_of_id is not null and amount<0))
);
create index debt_allocations_receivable_idx on public.debt_allocations(receivable_id,created_at,id);
create unique index debt_allocations_payment_receivable_key on public.debt_allocations(debt_payment_id,receivable_id) where debt_payment_id is not null;
create unique index debt_allocations_return_key on public.debt_allocations(sale_return_id) where sale_return_id is not null;
create unique index debt_allocations_sale_reversal_key on public.debt_allocations(sale_reversal_id) where sale_reversal_id is not null;
create unique index debt_allocations_reversal_key on public.debt_allocations(reversal_of_id) where reversal_of_id is not null;

-- Counterparty settlement ledger --------------------------------------------
create table public.settlement_entries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 branch_id uuid not null references public.branches(id) on delete restrict,counterparty_id uuid not null references public.counterparties(id) on delete restrict,
 entry_type text not null,amount_delta numeric(18,4) not null,currency_code char(3) not null,business_date date not null,
 source_document_type text not null,source_document_id uuid not null,
 reversal_of_id uuid references public.settlement_entries(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,
 approval_request_id uuid references public.approval_requests(id) on delete restrict,
 created_by uuid not null references public.organization_memberships(id) on delete restrict,created_at timestamptz not null default now(),
 constraint settlement_entries_type_check check(entry_type in('sale_debt','customer_payment','sale_return','purchase','supplier_payment','goods_taken','write_off','offset')),
 constraint settlement_entries_amount_check check(amount_delta<>0),
 constraint settlement_entries_currency_check check(currency_code::text~'^[A-Z]{3}$'),
 constraint settlement_entries_source_check check(source_document_type in('sale','sale_return','debt_payment','purchase','debt_allocation','cash_movement','goods_taken','offset'))
);
create unique index settlement_entries_primary_key on public.settlement_entries(source_document_type,source_document_id,entry_type) where reversal_of_id is null;
create unique index settlement_entries_reversal_key on public.settlement_entries(reversal_of_id) where reversal_of_id is not null;
create index settlement_entries_journal_idx on public.settlement_entries(organization_id,counterparty_id,currency_code,business_date,created_at,id);
create index settlement_entries_branch_idx on public.settlement_entries(branch_id,business_date,created_at,id);

create extension if not exists btree_gist with schema extensions;
create table public.settlement_periods(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 counterparty_id uuid not null references public.counterparties(id) on delete restrict,currency_code char(3) not null,
 starts_on date not null,ends_on date not null,status text not null default 'open',opening_balance numeric(18,4) not null default 0,
 closing_balance numeric(18,4),closed_by uuid references public.organization_memberships(id) on delete restrict,closed_at timestamptz,
 corrected_period_id uuid references public.settlement_periods(id) on delete restrict,
 created_by uuid not null references public.organization_memberships(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,created_at timestamptz not null default now(),
 constraint settlement_periods_currency_check check(currency_code::text~'^[A-Z]{3}$'),
 constraint settlement_periods_range_check check(starts_on<ends_on),
 constraint settlement_periods_status_check check(status in('open','closed','corrected')),
 constraint settlement_periods_state_check check((status='open'and closing_balance is null and closed_by is null and closed_at is null)or(status in('closed','corrected')and closing_balance is not null and closed_by is not null and closed_at is not null)),
 exclude using gist(organization_id with =,counterparty_id with =,currency_code with =,daterange(starts_on,ends_on,'[)')with &&),
 unique(command_id)
);
create unique index settlement_periods_one_correction on public.settlement_periods(corrected_period_id) where corrected_period_id is not null;
create index settlement_periods_journal_idx on public.settlement_periods(organization_id,counterparty_id,currency_code,starts_on desc);

create table public.settlement_acts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 settlement_period_id uuid not null unique references public.settlement_periods(id) on delete restrict,
 act_number text not null,total_debit numeric(18,4) not null,total_credit numeric(18,4) not null,closing_balance numeric(18,4) not null,
 snapshot_hash text not null,schema_version integer not null default 1,
 created_by uuid not null references public.organization_memberships(id) on delete restrict,
 command_id uuid not null references public.command_log(id) on delete restrict,created_at timestamptz not null default now(),
 constraint settlement_acts_number_check check(btrim(act_number)<>''),
 constraint settlement_acts_totals_check check(total_debit>=0 and total_credit>=0),
 constraint settlement_acts_hash_check check(snapshot_hash~'^[0-9a-f]{64}$'),
 constraint settlement_acts_schema_check check(schema_version>0),unique(organization_id,act_number),unique(command_id)
);
create table public.settlement_act_lines(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,
 settlement_act_id uuid not null references public.settlement_acts(id) on delete restrict,
 settlement_entry_id uuid not null references public.settlement_entries(id) on delete restrict,
 line_number integer not null,amount_delta numeric(18,4) not null,created_at timestamptz not null default now(),
 constraint settlement_act_lines_number_check check(line_number>0),
 constraint settlement_act_lines_amount_check check(amount_delta<>0),unique(settlement_act_id,line_number),unique(settlement_act_id,settlement_entry_id)
);

-- Defensive validation and write contexts -----------------------------------
create or replace function public.v2_debt_context_required() returns trigger language plpgsql set search_path='' as $$
begin if coalesce(current_setting('market_pos.debt_command',true),'')<>'on' then raise exception using errcode='P0001',message='V2_DEBT_COMMAND_CONTEXT_REQUIRED';end if;return coalesce(new,old);end$$;
create or replace function public.v2_settlement_context_required() returns trigger language plpgsql set search_path='' as $$
begin if coalesce(current_setting('market_pos.settlement_command',true),'')<>'on' then raise exception using errcode='P0001',message='V2_SETTLEMENT_COMMAND_CONTEXT_REQUIRED';end if;return coalesce(new,old);end$$;
create or replace function public.v2_financial_append_only() returns trigger language plpgsql set search_path='' as $$
begin raise exception using errcode='P0001',message='V2_FINANCIAL_APPEND_ONLY';end$$;

create or replace function public.v2_guard_receivable() returns trigger language plpgsql set search_path='' as $$
declare s public.sales_v2%rowtype;c public.counterparties%rowtype;m public.organization_memberships%rowtype;begin
 if tg_op='INSERT' then
  select * into s from public.sales_v2 where id=new.sale_id;
  select * into c from public.counterparties where id=new.counterparty_id;
  select * into m from public.organization_memberships where id=new.created_by;
  if s.id is null or c.id is null or m.id is null or s.organization_id<>new.organization_id or s.branch_id<>new.branch_id or s.customer_counterparty_id is distinct from new.counterparty_id or s.currency_code<>new.currency_code or c.organization_id<>new.organization_id or m.organization_id<>new.organization_id then raise exception using errcode='P0001',message='V2_RECEIVABLE_SCOPE_MISMATCH';end if;
 elsif (to_jsonb(new)-array['outstanding_amount','status','version','closed_at'])<>(to_jsonb(old)-array['outstanding_amount','status','version','closed_at']) then
  raise exception using errcode='P0001',message='V2_RECEIVABLE_IDENTITY_MUTATION_FORBIDDEN';
 end if;return new;end$$;

create or replace function public.v2_guard_debt_payment() returns trigger language plpgsql set search_path='' as $$
declare r public.registers%rowtype;s public.shifts_v2%rowtype;d public.devices_v2%rowtype;c public.counterparties%rowtype;m public.organization_memberships%rowtype;o public.debt_payments_v2%rowtype;begin
 if tg_op='INSERT' then
  select * into r from public.registers where id=new.register_id;select * into s from public.shifts_v2 where id=new.shift_id;select * into d from public.devices_v2 where id=new.device_id;select * into c from public.counterparties where id=new.counterparty_id;select * into m from public.organization_memberships where id=new.posted_by;
  if r.id is null or s.id is null or d.id is null or c.id is null or m.id is null or r.organization_id<>new.organization_id or r.branch_id<>new.branch_id or s.organization_id<>new.organization_id or s.branch_id<>new.branch_id or s.register_id<>new.register_id or d.organization_id<>new.organization_id or d.branch_id<>new.branch_id or d.register_id is distinct from new.register_id or c.organization_id<>new.organization_id or m.organization_id<>new.organization_id then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_SCOPE_MISMATCH';end if;
  if new.reversal_of_id is not null then select * into o from public.debt_payments_v2 where id=new.reversal_of_id;if o.id is null or o.reversal_of_id is not null or o.organization_id<>new.organization_id or o.branch_id<>new.branch_id or o.register_id<>new.register_id or o.counterparty_id<>new.counterparty_id or o.total_amount<>new.total_amount or o.currency_code<>new.currency_code then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_REVERSAL_MISMATCH';end if;end if;
 elsif (to_jsonb(new)-'status')<>(to_jsonb(old)-'status') or not(old.status='posted'and new.status='reversed') then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_IMMUTABLE';end if;return new;end$$;

create or replace function public.v2_guard_debt_allocation() returns trigger language plpgsql set search_path='' as $$
declare r public.receivables%rowtype;o public.debt_allocations%rowtype;begin
 select * into r from public.receivables where id=new.receivable_id;if r.id is null or r.organization_id<>new.organization_id then raise exception using errcode='P0001',message='V2_DEBT_ALLOCATION_SCOPE_MISMATCH';end if;
 if new.reversal_of_id is not null then select * into o from public.debt_allocations where id=new.reversal_of_id;if o.id is null or o.reversal_of_id is not null or o.receivable_id<>new.receivable_id or o.allocation_type<>new.allocation_type or new.amount<>-o.amount then raise exception using errcode='P0001',message='V2_DEBT_ALLOCATION_REVERSAL_MISMATCH';end if;end if;return new;end$$;

create or replace function public.v2_guard_settlement_entry() returns trigger language plpgsql set search_path='' as $$
declare b public.branches%rowtype;c public.counterparties%rowtype;o public.settlement_entries%rowtype;begin
 select * into b from public.branches where id=new.branch_id;select * into c from public.counterparties where id=new.counterparty_id;
 if b.id is null or c.id is null or b.organization_id<>new.organization_id or c.organization_id<>new.organization_id then raise exception using errcode='P0001',message='V2_SETTLEMENT_ENTRY_SCOPE_MISMATCH';end if;
 if exists(select 1 from public.settlement_periods p where p.organization_id=new.organization_id and p.counterparty_id=new.counterparty_id and p.currency_code=new.currency_code and p.status in('closed','corrected') and new.business_date>=p.starts_on and new.business_date<p.ends_on) then raise exception using errcode='P0001',message='V2_SETTLEMENT_PERIOD_CLOSED';end if;
 if new.reversal_of_id is not null then select * into o from public.settlement_entries where id=new.reversal_of_id;if o.id is null or o.reversal_of_id is not null or o.organization_id<>new.organization_id or o.counterparty_id<>new.counterparty_id or o.entry_type<>new.entry_type or o.currency_code<>new.currency_code or new.amount_delta<>-o.amount_delta then raise exception using errcode='P0001',message='V2_SETTLEMENT_REVERSAL_MISMATCH';end if;end if;return new;end$$;

create or replace function public.v2_guard_settlement_period() returns trigger language plpgsql set search_path='' as $$
declare c public.counterparties%rowtype;o public.settlement_periods%rowtype;begin
 if tg_op='INSERT' then select * into c from public.counterparties where id=new.counterparty_id;if c.id is null or c.organization_id<>new.organization_id then raise exception using errcode='P0001',message='V2_SETTLEMENT_PERIOD_SCOPE_MISMATCH';end if;if new.corrected_period_id is not null then select * into o from public.settlement_periods where id=new.corrected_period_id;if o.id is null or o.status<>'closed'or o.organization_id<>new.organization_id or o.counterparty_id<>new.counterparty_id or o.currency_code<>new.currency_code or new.starts_on<o.ends_on then raise exception using errcode='P0001',message='V2_SETTLEMENT_CORRECTION_MISMATCH';end if;end if;
 elsif not((old.status='open'and new.status='closed')or(old.status='closed'and new.status='corrected'))or(to_jsonb(new)-array['status','closing_balance','closed_by','closed_at'])<>(to_jsonb(old)-array['status','closing_balance','closed_by','closed_at']) then raise exception using errcode='P0001',message='V2_SETTLEMENT_PERIOD_IMMUTABLE';end if;return new;end$$;

create or replace function public.v2_guard_settlement_snapshot() returns trigger language plpgsql set search_path='' as $$
declare p public.settlement_periods%rowtype;a public.settlement_acts%rowtype;e public.settlement_entries%rowtype;begin
 if tg_table_name='settlement_acts' then select * into p from public.settlement_periods where id=new.settlement_period_id;if p.id is null or p.organization_id<>new.organization_id or p.status<>'closed'or p.closing_balance<>new.closing_balance then raise exception using errcode='P0001',message='V2_SETTLEMENT_ACT_SCOPE_MISMATCH';end if;
 else select * into a from public.settlement_acts where id=new.settlement_act_id;select * into e from public.settlement_entries where id=new.settlement_entry_id;if a.id is null or e.id is null or a.organization_id<>new.organization_id or e.organization_id<>new.organization_id or e.amount_delta<>new.amount_delta then raise exception using errcode='P0001',message='V2_SETTLEMENT_ACT_LINE_SCOPE_MISMATCH';end if;end if;return new;end$$;

create trigger v2_receivables_context before insert or update or delete on public.receivables for each row execute function public.v2_debt_context_required();
create trigger v2_receivables_guard before insert or update on public.receivables for each row execute function public.v2_guard_receivable();
create trigger v2_debt_payments_context before insert or update or delete on public.debt_payments_v2 for each row execute function public.v2_debt_context_required();
create trigger v2_debt_payments_guard before insert or update on public.debt_payments_v2 for each row execute function public.v2_guard_debt_payment();
create trigger v2_debt_allocations_context before insert on public.debt_allocations for each row execute function public.v2_debt_context_required();
create trigger v2_debt_allocations_guard before insert on public.debt_allocations for each row execute function public.v2_guard_debt_allocation();
create trigger v2_debt_allocations_append_only before update or delete on public.debt_allocations for each row execute function public.v2_financial_append_only();
create trigger v2_settlement_entries_context before insert on public.settlement_entries for each row execute function public.v2_settlement_context_required();
create trigger v2_settlement_entries_guard before insert on public.settlement_entries for each row execute function public.v2_guard_settlement_entry();
create trigger v2_settlement_entries_append_only before update or delete on public.settlement_entries for each row execute function public.v2_financial_append_only();
create trigger v2_settlement_periods_context before insert or update or delete on public.settlement_periods for each row execute function public.v2_settlement_context_required();
create trigger v2_settlement_periods_guard before insert or update on public.settlement_periods for each row execute function public.v2_guard_settlement_period();
create trigger v2_settlement_acts_context before insert on public.settlement_acts for each row execute function public.v2_settlement_context_required();
create trigger v2_settlement_acts_guard before insert on public.settlement_acts for each row execute function public.v2_guard_settlement_snapshot();
create trigger v2_settlement_acts_append_only before update or delete on public.settlement_acts for each row execute function public.v2_financial_append_only();
create trigger v2_settlement_act_lines_context before insert on public.settlement_act_lines for each row execute function public.v2_settlement_context_required();
create trigger v2_settlement_act_lines_guard before insert on public.settlement_act_lines for each row execute function public.v2_guard_settlement_snapshot();
create trigger v2_settlement_act_lines_append_only before update or delete on public.settlement_act_lines for each row execute function public.v2_financial_append_only();

-- Projection and authorization helpers --------------------------------------
create or replace function public.v2_recompute_receivable(i uuid) returns public.receivables language plpgsql security definer set search_path='' as $$
declare r public.receivables%rowtype;x numeric;st text;previous_context text:=coalesce(current_setting('market_pos.debt_command',true),'');begin select * into r from public.receivables where id=i for update;if not found then raise exception using errcode='P0001',message='V2_RECEIVABLE_NOT_FOUND';end if;select r.original_amount-coalesce(sum(a.amount),0) into x from public.debt_allocations a where a.receivable_id=i;if x<0 or x>r.original_amount then raise exception using errcode='P0001',message='V2_RECEIVABLE_RECONCILIATION_FAILED';end if;st:=case when x=r.original_amount then'open'when x>0 then'partial'when exists(select 1 from public.debt_allocations a where a.receivable_id=i and a.allocation_type='sale_reversal'and a.amount>0 and not exists(select 1 from public.debt_allocations z where z.reversal_of_id=a.id))then'reversed'when exists(select 1 from public.debt_allocations a where a.receivable_id=i and a.allocation_type='write_off'and a.amount>0 and not exists(select 1 from public.debt_allocations z where z.reversal_of_id=a.id))then'written_off'else'paid'end;perform set_config('market_pos.debt_command','on',true);update public.receivables set outstanding_amount=x,status=st,version=version+1,closed_at=case when x=0 then coalesce(closed_at,clock_timestamp())else null end where id=i returning * into r;perform set_config('market_pos.debt_command',previous_context,true);return r;end$$;

create or replace function public.v2_can_view_debt(o uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$select public.v2_has_permission(o,'debts.view',b)or public.v2_has_permission(o,'debts.collect',b)or public.v2_has_support_grant(o,'debts.view')$$;
create or replace function public.v2_can_view_settlement(o uuid,b uuid,t text) returns boolean language sql stable security definer set search_path='' as $$select (public.v2_has_permission(o,'settlements.view',b)or public.v2_has_permission(o,'settlements.manage',b)or public.v2_has_support_grant(o,'settlements.view'))and(t<>'purchase'or public.v2_has_permission(o,'purchases.cost.view',b)or public.v2_has_support_grant(o,'purchases.cost.view'))$$;

create or replace function public.v2_receivable_journal(o uuid,b uuid default null) returns table(id uuid,branch_id uuid,counterparty_id uuid,sale_id uuid,original_amount numeric,outstanding_amount numeric,currency_code char(3),due_date date,status text,version bigint,created_at timestamptz,closed_at timestamptz) language sql stable security definer set search_path='' as $$select r.id,r.branch_id,r.counterparty_id,r.sale_id,r.original_amount,r.outstanding_amount,r.currency_code,r.due_date,r.status,r.version,r.created_at,r.closed_at from public.receivables r where r.organization_id=o and(b is null or r.branch_id=b)and public.v2_can_view_debt(o,r.branch_id)$$;
create or replace function public.v2_debt_payment_journal(o uuid,b uuid default null) returns table(id uuid,branch_id uuid,register_id uuid,counterparty_id uuid,shift_id uuid,document_number text,business_date date,total_amount numeric,currency_code char(3),status text,posted_at timestamptz,reversal_of_id uuid) language sql stable security definer set search_path='' as $$select d.id,d.branch_id,d.register_id,d.counterparty_id,d.shift_id,d.document_number,d.business_date,d.total_amount,d.currency_code,d.status,d.posted_at,d.reversal_of_id from public.debt_payments_v2 d where d.organization_id=o and(b is null or d.branch_id=b)and public.v2_can_view_debt(o,d.branch_id)$$;
create or replace function public.v2_settlement_journal(o uuid,cp uuid,cur char(3)) returns table(id uuid,branch_id uuid,entry_type text,amount_delta numeric,business_date date,source_document_type text,source_document_id uuid,reversal_of_id uuid,created_at timestamptz) language sql stable security definer set search_path='' as $$select e.id,e.branch_id,e.entry_type,e.amount_delta,e.business_date,e.source_document_type,e.source_document_id,e.reversal_of_id,e.created_at from public.settlement_entries e where e.organization_id=o and e.counterparty_id=cp and e.currency_code=cur and public.v2_can_view_settlement(o,e.branch_id,e.entry_type) order by e.business_date,e.created_at,e.id$$;
create or replace function public.v2_counterparty_balance(o uuid,cp uuid,cur char(3)) returns numeric language sql stable security definer set search_path='' as $$select coalesce(sum(e.amount_delta),0) from public.settlement_entries e where e.organization_id=o and e.counterparty_id=cp and e.currency_code=cur and public.v2_can_view_settlement(o,e.branch_id,e.entry_type)$$;
create or replace function public.v2_settlement_act(i uuid) returns table(act_id uuid,period_id uuid,act_number text,line_number integer,entry_id uuid,amount_delta numeric,snapshot_hash text) language sql stable security definer set search_path='' as $$select a.id,a.settlement_period_id,a.act_number,l.line_number,l.settlement_entry_id,l.amount_delta,a.snapshot_hash from public.settlement_acts a join public.settlement_periods p on p.id=a.settlement_period_id left join public.settlement_act_lines l on l.settlement_act_id=a.id where a.id=i and(public.v2_has_permission(a.organization_id,'settlements.view',null)or public.v2_has_permission(a.organization_id,'settlements.manage',null)or public.v2_has_support_grant(a.organization_id,'settlements.view'))order by l.line_number$$;

-- Row level security and grants ----------------------------------------------
alter table public.receivables enable row level security;alter table public.debt_payments_v2 enable row level security;alter table public.debt_allocations enable row level security;alter table public.settlement_entries enable row level security;alter table public.settlement_periods enable row level security;alter table public.settlement_acts enable row level security;alter table public.settlement_act_lines enable row level security;
create policy receivables_select on public.receivables for select to authenticated using(public.v2_can_view_debt(organization_id,branch_id));
create policy debt_payments_v2_select on public.debt_payments_v2 for select to authenticated using(public.v2_can_view_debt(organization_id,branch_id));
create policy debt_allocations_select on public.debt_allocations for select to authenticated using(exists(select 1 from public.receivables r where r.id=receivable_id and public.v2_can_view_debt(r.organization_id,r.branch_id)));
create policy settlement_entries_select on public.settlement_entries for select to authenticated using(public.v2_can_view_settlement(organization_id,branch_id,entry_type));
create policy settlement_periods_select on public.settlement_periods for select to authenticated using(public.v2_has_permission(organization_id,'settlements.view',null)or public.v2_has_permission(organization_id,'settlements.manage',null)or public.v2_has_support_grant(organization_id,'settlements.view'));
create policy settlement_acts_select on public.settlement_acts for select to authenticated using(exists(select 1 from public.settlement_periods p where p.id=settlement_period_id and(public.v2_has_permission(p.organization_id,'settlements.view',null)or public.v2_has_permission(p.organization_id,'settlements.manage',null)or public.v2_has_support_grant(p.organization_id,'settlements.view'))));
create policy settlement_act_lines_select on public.settlement_act_lines for select to authenticated using(exists(select 1 from public.settlement_acts a join public.settlement_periods p on p.id=a.settlement_period_id where a.id=settlement_act_id and(public.v2_has_permission(p.organization_id,'settlements.view',null)or public.v2_has_permission(p.organization_id,'settlements.manage',null)or public.v2_has_support_grant(p.organization_id,'settlements.view'))));

revoke all on public.receivables,public.debt_payments_v2,public.debt_allocations,public.settlement_entries,public.settlement_periods,public.settlement_acts,public.settlement_act_lines from anon,authenticated,service_role;
grant select on public.receivables,public.debt_payments_v2,public.debt_allocations,public.settlement_entries,public.settlement_periods,public.settlement_acts,public.settlement_act_lines to authenticated;
revoke execute on function public.v2_debt_context_required(),public.v2_settlement_context_required(),public.v2_financial_append_only(),public.v2_guard_receivable(),public.v2_guard_debt_payment(),public.v2_guard_debt_allocation(),public.v2_guard_settlement_entry(),public.v2_guard_settlement_period(),public.v2_guard_settlement_snapshot(),public.v2_recompute_receivable(uuid),public.v2_can_view_debt(uuid,uuid),public.v2_can_view_settlement(uuid,uuid,text) from public,anon,authenticated;
revoke execute on function public.v2_receivable_journal(uuid,uuid),public.v2_debt_payment_journal(uuid,uuid),public.v2_settlement_journal(uuid,uuid,character),public.v2_counterparty_balance(uuid,uuid,character),public.v2_settlement_act(uuid) from public,anon;
grant execute on function public.v2_receivable_journal(uuid,uuid),public.v2_debt_payment_journal(uuid,uuid),public.v2_settlement_journal(uuid,uuid,character),public.v2_counterparty_balance(uuid,uuid,character),public.v2_settlement_act(uuid) to authenticated;
grant execute on function public.v2_can_view_debt(uuid,uuid),public.v2_can_view_settlement(uuid,uuid,text)to authenticated;

-- 0015 integration guards ----------------------------------------------------
create or replace function public.v2_payment_guard()returns trigger language plpgsql set search_path=''as $$
declare o uuid;b uuid;r uuid;s uuid;c char(3);original public.payments_v2%rowtype;refunded numeric;begin
 if new.sale_id is not null then select organization_id,branch_id,register_id,shift_id,currency_code into o,b,r,s,c from public.sales_v2 where id=new.sale_id;
 elsif new.sale_return_id is not null then select sr.organization_id,sv.branch_id,sr.register_id,sr.shift_id,sv.currency_code into o,b,r,s,c from public.sale_returns sr join public.sales_v2 sv on sv.id=sr.original_sale_id where sr.id=new.sale_return_id;
 else select organization_id,branch_id,register_id,shift_id,currency_code into o,b,r,s,c from public.debt_payments_v2 where id=new.debt_payment_id;end if;
 if new.organization_id is distinct from o or new.branch_id is distinct from b or new.register_id is distinct from r or new.shift_id is distinct from s or new.currency_code<>c then raise exception using errcode='P0001',message='V2_PAYMENT_SOURCE_SCOPE_MISMATCH';end if;
 if new.reversal_of_id is not null then select * into original from public.payments_v2 where id=new.reversal_of_id;if not found or original.organization_id<>new.organization_id or original.method<>new.method or original.currency_code<>new.currency_code then raise exception using errcode='P0001',message='V2_PAYMENT_REVERSAL_MISMATCH';end if;
  if original.amount>0 and new.sale_return_id is not null then select coalesce(sum(abs(p.amount)),0)into refunded from public.payments_v2 p where p.reversal_of_id=original.id and p.amount<0 and p.status='confirmed'and not exists(select 1 from public.payments_v2 z where z.reversal_of_id=p.id and z.amount>0 and z.status='confirmed');if new.amount>=0 or refunded+abs(new.amount)>original.amount then raise exception using errcode='P0001',message='V2_PAYMENT_REFUND_EXCEEDED';end if;
  elsif new.amount<>-original.amount then raise exception using errcode='P0001',message='V2_PAYMENT_REVERSAL_MISMATCH';end if;
 elsif new.sale_id is not null or new.debt_payment_id is not null then if new.amount<=0 then raise exception using errcode='P0001',message='V2_PAYMENT_SIGN_MISMATCH';end if;
 else raise exception using errcode='P0001',message='V2_PAYMENT_REFUND_SOURCE_REQUIRED';end if;return new;end$$;

create or replace function public.v2_sale_graph_guard()returns trigger language plpgsql set search_path=''as $$
declare o uuid;b uuid;r uuid;w uuid;s uuid;begin
 if tg_table_name='sales_v2'then
  if not exists(select 1 from public.registers x where x.id=new.register_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.warehouses x where x.id=new.warehouse_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.devices_v2 x where x.id=new.device_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id and x.status='trusted')or not exists(select 1 from public.shifts_v2 x where x.id=new.shift_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id)then raise exception using errcode='P0001',message='V2_SALE_LOCATION_SCOPE_MISMATCH';end if;
  if new.customer_counterparty_id is not null and not exists(select 1 from public.counterparty_roles cr where cr.counterparty_id=new.customer_counterparty_id and cr.organization_id=new.organization_id and cr.role_code='customer'and cr.ended_at is null)then raise exception using errcode='P0001',message='V2_SALE_ACTIVE_CUSTOMER_REQUIRED';end if;
  if tg_op='UPDATE'and(to_jsonb(new)-'status')<>(to_jsonb(old)-'status')then raise exception using errcode='P0001',message='V2_SALE_POSTED_IMMUTABLE';end if;
 elsif tg_table_name='sale_lines_v2'then select organization_id,branch_id,register_id,warehouse_id,shift_id into o,b,r,w,s from public.sales_v2 where id=new.sale_id;if o is distinct from new.organization_id then raise exception using errcode='P0001',message='V2_SALE_LINE_SCOPE_MISMATCH';end if;
 elsif tg_table_name='sale_line_batch_allocations'then select sl.organization_id,sv.warehouse_id into o,w from public.sale_lines_v2 sl join public.sales_v2 sv on sv.id=sl.sale_id where sl.id=new.sale_line_id;if o is distinct from new.organization_id or not exists(select 1 from public.product_batches_v2 pb join public.sale_lines_v2 sl on sl.id=new.sale_line_id where pb.id=new.product_batch_id and pb.organization_id=new.organization_id and pb.warehouse_id=w and pb.product_id=sl.product_id)then raise exception using errcode='P0001',message='V2_SALE_ALLOCATION_SCOPE_MISMATCH';end if;end if;return new;end$$;

-- Authenticated debt commands ------------------------------------------------
create or replace function public.v2_record_debt_payment(organization_id uuid,branch_id uuid,register_id uuid,current_shift_id uuid,counterparty_id uuid,document_number text,business_date date,currency_code char(3),device_id uuid,local_operation_id uuid,client_created_at timestamptz,payments jsonb,allocations jsonb)returns uuid language plpgsql security definer set search_path=''as $$
declare a uuid:=public.v2_current_membership_id(organization_id);c uuid;d uuid:=gen_random_uuid();p jsonb:=jsonb_build_object('organization_id',organization_id,'branch_id',branch_id,'register_id',register_id,'shift_id',current_shift_id,'counterparty_id',counterparty_id,'document_number',document_number,'business_date',business_date,'currency_code',currency_code,'device_id',device_id,'client_created_at',client_created_at,'payments',payments,'allocations',allocations);item jsonb;rid uuid;amt numeric;total numeric:=0;allocated numeric:=0;entry_id uuid;rr public.receivables%rowtype;begin
 if not public.v2_has_permission(organization_id,'debts.collect',branch_id)then raise exception using errcode='P0001',message='V2_DEBTS_COLLECT_REQUIRED';end if;
 c:=public.v2_begin_inventory_command(organization_id,branch_id,device_id,local_operation_id,'debt_payment.record',p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;
 perform public.v2_require_open_sales_shift(organization_id,branch_id,register_id,current_shift_id,device_id,a);
 if jsonb_typeof(payments)<>'array'or jsonb_array_length(payments)=0 then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_METHODS_REQUIRED';end if;
 for item in select value from jsonb_array_elements(payments) loop if item->>'method'not in('cash','card','transfer')or coalesce((item->>'amount')::numeric,0)<=0 then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_METHOD_INVALID';end if;total:=total+(item->>'amount')::numeric;end loop;
 perform set_config('market_pos.debt_command','on',true);perform set_config('market_pos.sales_command','on',true);perform set_config('market_pos.settlement_command','on',true);
 insert into public.debt_payments_v2(id,organization_id,branch_id,register_id,counterparty_id,shift_id,document_number,business_date,total_amount,currency_code,device_id,local_operation_id,client_created_at,posted_by,command_id)values(d,organization_id,branch_id,register_id,counterparty_id,current_shift_id,document_number,business_date,total,currency_code,device_id,local_operation_id,client_created_at,a,c);
 for item in select value from jsonb_array_elements(payments) loop insert into public.payments_v2(organization_id,branch_id,register_id,shift_id,debt_payment_id,method,amount,currency_code,device_id,local_operation_id,created_by)values(organization_id,branch_id,register_id,current_shift_id,d,item->>'method',(item->>'amount')::numeric,currency_code,device_id,coalesce((item->>'local_operation_id')::uuid,gen_random_uuid()),a);update public.shift_totals set expected_amount=expected_amount+(item->>'amount')::numeric,version=version+1,updated_at=now()where shift_id=current_shift_id and payment_method=item->>'method';end loop;
 if allocations is null or allocations='[]'::jsonb then
  for rid,amt in select r.id,least(r.outstanding_amount,total-allocated)from public.receivables r join public.sales_v2 s on s.id=r.sale_id where r.organization_id=$1 and r.branch_id=$2 and r.counterparty_id=$5 and r.currency_code=$8 and r.status in('open','partial')order by r.due_date nulls last,s.business_date,r.id for update of r loop exit when allocated>=total;insert into public.debt_allocations(organization_id,receivable_id,debt_payment_id,allocation_type,amount,command_id,created_by)values($1,rid,d,'payment',amt,c,a);allocated:=allocated+amt;select * into rr from public.v2_recompute_receivable(rid);perform public.v2_emit_domain_event(organization_id,branch_id,device_id,a,c,null,'receivable',rid,case when rr.status='paid'then'debt.closed'else'debt.partially_repaid'end,case when rr.status='paid'then'DebtClosed'else'DebtPartiallyRepaid'end,jsonb_build_object('receivable_id',rid,'outstanding_amount',rr.outstanding_amount));end loop;
 else for item in select value from jsonb_array_elements(allocations)loop rid:=(item->>'receivable_id')::uuid;amt:=(item->>'amount')::numeric;if not exists(select 1 from public.receivables r where r.id=rid and r.organization_id=$1 and r.branch_id=$2 and r.counterparty_id=$5 and r.currency_code=$8 and r.status in('open','partial')and r.outstanding_amount>=amt)then raise exception using errcode='P0001',message='V2_DEBT_ALLOCATION_INVALID';end if;insert into public.debt_allocations(organization_id,receivable_id,debt_payment_id,allocation_type,amount,command_id,created_by)values($1,rid,d,'payment',amt,c,a);allocated:=allocated+amt;select * into rr from public.v2_recompute_receivable(rid);perform public.v2_emit_domain_event(organization_id,branch_id,device_id,a,c,null,'receivable',rid,case when rr.status='paid'then'debt.closed'else'debt.partially_repaid'end,case when rr.status='paid'then'DebtClosed'else'DebtPartiallyRepaid'end,jsonb_build_object('receivable_id',rid,'outstanding_amount',rr.outstanding_amount));end loop;end if;
 if allocated<>total then raise exception using errcode='P0001',message='V2_DEBT_PAYMENT_UNALLOCATED';end if;
 entry_id:=gen_random_uuid();insert into public.settlement_entries(id,organization_id,branch_id,counterparty_id,entry_type,amount_delta,currency_code,business_date,source_document_type,source_document_id,command_id,created_by)values(entry_id,organization_id,branch_id,counterparty_id,'customer_payment',-total,currency_code,business_date,'debt_payment',d,c,a);
 perform public.v2_emit_domain_event(organization_id,branch_id,device_id,a,c,null,'debt_payment',d,'debt_payment.recorded','DebtPaymentRecorded',jsonb_build_object('debt_payment_id',d,'amount',total,'currency_code',currency_code));perform public.v2_emit_domain_event(organization_id,branch_id,device_id,a,c,null,'settlement_entry',entry_id,'settlement.entry.posted','SettlementEntryPosted',jsonb_build_object('settlement_entry_id',entry_id,'source_type','debt_payment','source_id',d));perform public.v2_complete_inventory_command(c,'debt_payment',d,jsonb_build_object('id',d));perform set_config('market_pos.settlement_command','off',true);perform set_config('market_pos.sales_command','off',true);perform set_config('market_pos.debt_command','off',true);return d;end$$;

create or replace function public.v2_write_off_receivable(receivable_id uuid,amount numeric,reason text,local_operation_id uuid,approval_id uuid)returns uuid language plpgsql security definer set search_path=''as $$
declare r public.receivables%rowtype;a uuid;c uuid;i uuid:=gen_random_uuid();e uuid:=gen_random_uuid();p jsonb;begin select * into r from public.receivables where id=receivable_id for update;if not found then raise exception using errcode='P0001',message='V2_RECEIVABLE_NOT_FOUND';end if;if not public.v2_has_permission(r.organization_id,'debts.write_off',r.branch_id)then raise exception using errcode='P0001',message='V2_DEBTS_WRITE_OFF_REQUIRED';end if;if amount<=0 or amount>r.outstanding_amount or nullif(btrim(reason),'')is null then raise exception using errcode='P0001',message='V2_DEBT_WRITE_OFF_INVALID';end if;a:=public.v2_current_membership_id(r.organization_id);p:=jsonb_build_object('receivable_id',receivable_id,'amount',amount,'reason',reason);c:=public.v2_use_approved_command(approval_id,r.organization_id,'debts.write_off',local_operation_id,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;perform set_config('market_pos.debt_command','on',true);perform set_config('market_pos.settlement_command','on',true);insert into public.debt_allocations(id,organization_id,receivable_id,allocation_type,amount,command_id,approval_request_id,created_by)values(i,r.organization_id,receivable_id,'write_off',amount,c,approval_id,a);perform public.v2_recompute_receivable(receivable_id);insert into public.settlement_entries(id,organization_id,branch_id,counterparty_id,entry_type,amount_delta,currency_code,business_date,source_document_type,source_document_id,command_id,approval_request_id,created_by)values(e,r.organization_id,r.branch_id,r.counterparty_id,'write_off',-amount,r.currency_code,current_date,'debt_allocation',i,c,approval_id,a);perform public.v2_emit_domain_event(r.organization_id,r.branch_id,null,a,c,approval_id,'debt_allocation',i,'debt.written_off','DebtWrittenOff',jsonb_build_object('receivable_id',receivable_id,'allocation_id',i,'amount',amount));perform public.v2_emit_domain_event(r.organization_id,r.branch_id,null,a,c,approval_id,'settlement_entry',e,'settlement.entry.posted','SettlementEntryPosted',jsonb_build_object('settlement_entry_id',e,'source_type','debt_allocation','source_id',i));perform public.v2_complete_inventory_command(c,'debt_allocation',i,jsonb_build_object('id',i));perform set_config('market_pos.settlement_command','off',true);perform set_config('market_pos.debt_command','off',true);return i;end$$;

create or replace function public.v2_reverse_receivable_write_off(write_off_allocation_id uuid,local_operation_id uuid,approval_id uuid,payload jsonb default'{}')returns uuid language plpgsql security definer set search_path=''as $$
