create or replace function public.v2_close_settlement_period(organization_id uuid,counterparty_id uuid,currency_code char(3),starts_on date,ends_on date,act_number text,corrected_period_id uuid,local_operation_id uuid,approval_id uuid)returns uuid language plpgsql security definer set search_path=''as $$
