 for pay in select p0.* from public.payments_v2 p0 where p0.debt_payment_id=d.id and p0.reversal_of_id is null order by p0.id loop np:=gen_random_uuid();insert into public.payments_v2(id,organization_id,branch_id,register_id,shift_id,debt_payment_id,method,amount,currency_code,device_id,local_operation_id,reversal_of_id,created_by)values(np,d.organization_id,d.branch_id,d.register_id,current_shift_id,r,pay.method,-pay.amount,pay.currency_code,device_id,gen_random_uuid(),pay.id,a);update public.shift_totals set expected_amount=expected_amount-pay.amount,version=version+1,updated_at=now()where shift_id=current_shift_id and payment_method=pay.method;end loop;
 for al in select a0.* from public.debt_allocations a0 where a0.debt_payment_id=d.id and a0.reversal_of_id is null order by a0.receivable_id,a0.id loop na:=gen_random_uuid();insert into public.debt_allocations(id,organization_id,receivable_id,debt_payment_id,allocation_type,amount,reversal_of_id,command_id,approval_request_id,created_by)values(na,d.organization_id,al.receivable_id,r,'payment',-al.amount,al.id,c,approval_id,a);select * into rr from public.v2_recompute_receivable(al.receivable_id);perform public.v2_emit_domain_event(d.organization_id,d.branch_id,device_id,a,c,approval_id,'receivable',rr.id,'debt.reopened','DebtReopened',jsonb_build_object('receivable_id',rr.id,'outstanding_amount',rr.outstanding_amount));end loop;
