-- Purchase settlement integration is attached to the hardened 0013 lifecycle.
create or replace function public.v2_purchase_settlement_entry()returns trigger language plpgsql set search_path=''as $$
declare c uuid;e public.settlement_entries%rowtype;amount_ numeric;entry_id uuid;aid uuid;begin
 if new.status='posted'and old.status is distinct from'posted'and new.counterparty_id is not null then
  select id into c from public.command_log where organization_id=new.organization_id and local_operation_id=new.local_operation_id limit 1;
  if c is null then raise exception using errcode='P0001',message='V2_PURCHASE_SETTLEMENT_COMMAND_REQUIRED';end if;select id into aid from public.approval_requests where command_id=c and status='approved'order by decided_at desc nulls last limit 1;
  perform set_config('market_pos.settlement_command','on',true);
  if new.reversal_of_id is null then
   insert into public.settlement_entries(organization_id,branch_id,counterparty_id,entry_type,amount_delta,currency_code,business_date,source_document_type,source_document_id,command_id,approval_request_id,created_by)values(new.organization_id,new.branch_id,new.counterparty_id,'purchase',-new.total_amount,new.currency_code,new.business_date,'purchase',new.id,c,aid,new.posted_by)returning id into entry_id;perform public.v2_emit_domain_event(new.organization_id,new.branch_id,null,new.posted_by,c,aid,'settlement_entry',entry_id,'settlement.entry.posted','SettlementEntryPosted',jsonb_build_object('settlement_entry_id',entry_id,'source_type','purchase','source_id',new.id));
  else select * into e from public.settlement_entries where source_document_type='purchase'and source_document_id=new.reversal_of_id and entry_type='purchase'and reversal_of_id is null;amount_:=-e.amount_delta;if e.id is null or e.organization_id<>new.organization_id or e.counterparty_id<>new.counterparty_id or e.currency_code<>new.currency_code or amount_<>new.total_amount then raise exception using errcode='P0001',message='V2_PURCHASE_SETTLEMENT_REVERSAL_MISMATCH';end if;insert into public.settlement_entries(organization_id,branch_id,counterparty_id,entry_type,amount_delta,currency_code,business_date,source_document_type,source_document_id,reversal_of_id,command_id,approval_request_id,created_by)values(new.organization_id,new.branch_id,new.counterparty_id,'purchase',amount_,new.currency_code,new.business_date,'purchase',new.id,e.id,c,aid,new.posted_by)returning id into entry_id;perform public.v2_emit_domain_event(new.organization_id,new.branch_id,null,new.posted_by,c,aid,'settlement_entry',entry_id,'settlement.entry.reversed','SettlementEntryReversed',jsonb_build_object('settlement_entry_id',entry_id,'reversal_of_id',e.id,'source_type','purchase','source_id',new.id));end if;
  perform set_config('market_pos.settlement_command','off',true);
 end if;return new;end$$;
create trigger v2_purchase_settlement_after_post after update of status on public.purchase_documents for each row execute function public.v2_purchase_settlement_entry();

