-- Debt-aware sale posting. The 0014 signature below is retained as a wrapper.
create or replace function public.v2_post_sale(o uuid,b uuid,r uuid,w uuid,sh uuid,customer uuid,n text,bd date,cur char(3),d uuid,op uuid,client_at timestamptz,lines jsonb,pays jsonb,approval uuid,debt_terms jsonb)returns uuid language plpgsql security definer set search_path=''as $$
declare i uuid:=gen_random_uuid();a uuid:=public.v2_current_membership_id(o);c uuid;p jsonb:=jsonb_build_object('organization_id',o,'branch_id',b,'register_id',r,'warehouse_id',w,'shift_id',sh,'customer_id',customer,'document_number',n,'business_date',bd,'currency_code',cur,'device_id',d,'client_created_at',client_at,'lines',lines,'payments',pays,'approval_id',approval,'debt_terms',coalesce(debt_terms,'{}'::jsonb));pl uuid;ln jsonb;pay jsonb;line_id uuid;alloc_id uuid;movement_id uuid;prod uuid;unit uuid;price_id uuid;effective timestamptz;q numeric;factor numeric;base numeric;price numeric;disc numeric;line_total numeric;subtotal numeric:=0;discount numeric:=0;total numeric;paid numeric:=0;debt numeric;limit_ numeric;remaining numeric;take numeric;cost_sum numeric;batch record;cs public.counterparty_credit_settings%rowtype;cp public.counterparties%rowtype;due date;exposure numeric;override_needed boolean:=false;receivable_id uuid;settlement_id uuid;begin
 if not public.v2_has_permission(o,'sales.post',b)then raise exception using errcode='P0001',message='V2_SALES_POST_REQUIRED';end if;c:=public.v2_begin_inventory_command(o,b,d,op,'sale.post',p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;
 perform public.v2_require_open_sales_shift(o,b,r,sh,d,a);if not exists(select 1 from public.warehouses z where z.id=w and z.organization_id=o and z.branch_id=b)then raise exception using errcode='P0001',message='V2_SALE_LOCATION_SCOPE_MISMATCH';end if;
 select id into pl from public.price_lists where organization_id=o and status='active'and is_default and(branch_id=b or branch_id is null)order by(branch_id is not null)desc limit 1;if pl is null then raise exception using errcode='P0001',message='V2_SALE_PRICE_NOT_FOUND';end if;if(select currency_code from public.price_lists where id=pl)<>cur then raise exception using errcode='P0001',message='V2_SALE_PRICE_STALE';end if;if jsonb_typeof(lines)<>'array'or jsonb_array_length(lines)=0 then raise exception using errcode='P0001',message='V2_SALE_LINES_REQUIRED';end if;
 for ln in select value from jsonb_array_elements(lines)loop prod:=(ln->>'product_id')::uuid;unit:=(ln->>'unit_id')::uuid;price_id:=(ln->>'product_price_id')::uuid;effective:=(ln->>'effective_at')::timestamptz;q:=(ln->>'quantity')::numeric;factor:=(ln->>'unit_factor')::numeric;base:=q*factor;price:=(ln->>'unit_sale_price')::numeric;disc:=coalesce((ln->>'discount_amount')::numeric,0);if coalesce((ln->>'tax_amount')::numeric,0)<>0 then raise exception using errcode='P0001',message='V2_SALE_TAX_NOT_CONFIGURED';end if;if not exists(select 1 from public.product_prices pp where pp.id=price_id and pp.organization_id=o and pp.product_id=prod and pp.price_list_id=pl and pp.currency_code=cur and pp.amount=price and effective>=pp.valid_from and(pp.valid_to is null or effective<pp.valid_to))then if exists(select 1 from public.product_prices where id=price_id)then raise exception using errcode='P0001',message='V2_SALE_PRICE_STALE';else raise exception using errcode='P0001',message='V2_SALE_PRICE_NOT_FOUND';end if;end if;line_total:=round(q*price-disc,4);if line_total<0 then raise exception using errcode='P0001',message='V2_SALE_DISCOUNT_LIMIT_EXCEEDED';end if;subtotal:=subtotal+round(q*price,4);discount:=discount+disc;end loop;total:=subtotal-discount;
 limit_:=public.v2_effective_discount_limit(o);if discount>0 and not public.v2_has_permission(o,'sales.discount',b)then raise exception using errcode='P0001',message='V2_SALE_DISCOUNT_REQUIRED';end if;if exists(select 1 from jsonb_array_elements(lines)z where coalesce((z->>'discount_amount')::numeric,0)*100/nullif((z->>'quantity')::numeric*(z->>'unit_sale_price')::numeric,0)>limit_)or discount*100/nullif(subtotal,0)>limit_ then if not public.v2_has_permission(o,'sales.discount.override',b)then raise exception using errcode='P0001',message='V2_SALE_DISCOUNT_LIMIT_EXCEEDED';end if;perform public.v2_require_domain_approval(approval,c,o,'sales.discount.override');end if;
 if jsonb_typeof(coalesce(pays,'[]'::jsonb))<>'array'then raise exception using errcode='P0001',message='V2_SALE_PAYMENTS_INVALID';end if;for pay in select value from jsonb_array_elements(coalesce(pays,'[]'::jsonb))loop if pay->>'method'not in('cash','card','transfer')then raise exception using errcode='P0001',message='V2_PAYMENT_METHOD_UNSUPPORTED';end if;if coalesce((pay->>'amount')::numeric,0)<=0 then raise exception using errcode='P0001',message='V2_PAYMENT_SIGN_MISMATCH';end if;paid:=paid+(pay->>'amount')::numeric;end loop;if paid>total then raise exception using errcode='P0001',message='V2_SALE_PAYMENT_EXCEEDS_TOTAL';end if;debt:=total-paid;
 if debt>0 then
  if customer is null then raise exception using errcode='P0001',message='V2_SALE_DEBT_CUSTOMER_REQUIRED';end if;if not public.v2_has_permission(o,'debts.create',b)then raise exception using errcode='P0001',message='V2_DEBTS_CREATE_REQUIRED';end if;
  if debt_terms is null then debt_terms:='{}'::jsonb;end if;if jsonb_typeof(debt_terms)<>'object'or exists(select 1 from jsonb_object_keys(debt_terms)k where k<>'due_date')then raise exception using errcode='P0001',message='V2_SALE_DEBT_TERMS_INVALID';end if;
  select * into cp from public.counterparties where id=customer and organization_id=o; if not found then raise exception using errcode='P0001',message='V2_SALE_CUSTOMER_TENANT_MISMATCH';end if;
  if not exists(select 1 from public.counterparty_roles cr where cr.counterparty_id=customer and cr.organization_id=o and cr.role_code='customer'and cr.ended_at is null)then raise exception using errcode='P0001',message='V2_SALE_ACTIVE_CUSTOMER_REQUIRED';end if;
  select * into cs from public.counterparty_credit_settings where counterparty_id=customer and organization_id=o;due:=coalesce((debt_terms->>'due_date')::date,bd+coalesce(cs.max_due_days,0));select coalesce(sum(rr.outstanding_amount),0)into exposure from public.receivables rr where rr.organization_id=o and rr.counterparty_id=customer and rr.currency_code=cur and rr.status in('open','partial');
  override_needed:=cs.counterparty_id is null or not cs.credit_enabled or cs.currency_code<>cur or due>bd+cs.max_due_days or exposure+debt>cs.credit_limit_amount or cp.status='archived';
  if override_needed then if not public.v2_has_permission(o,'debts.limit.override',b)then raise exception using errcode='P0001',message='V2_DEBT_LIMIT_OVERRIDE_REQUIRED';end if;perform public.v2_require_domain_approval(approval,c,o,'debts.limit.override');end if;
