alter function public.v2_reverse_sale(uuid,uuid,text,uuid,uuid,uuid,jsonb)rename to v2_reverse_sale_0014;
create function public.v2_reverse_sale(sale uuid,sh uuid,n text,d uuid,op uuid,approval uuid,payload jsonb default'{}')returns uuid language plpgsql security definer set search_path=''as $$
declare s public.sales_v2%rowtype;rec public.receivables%rowtype;r uuid:=gen_random_uuid();a uuid;c uuid;p jsonb:=payload||jsonb_build_object('sale_id',sale,'shift_id',sh,'document_number',n,'device_id',d);l public.sale_lines_v2%rowtype;nl uuid;al public.sale_line_batch_allocations%rowtype;na uuid;mv uuid;pay public.payments_v2%rowtype;np uuid;scopes jsonb;da uuid;primary_entry public.settlement_entries%rowtype;se uuid;begin
 select * into s from public.sales_v2 where id=sale for update;if not found then raise exception using errcode='P0001',message='V2_SALE_NOT_FOUND';end if;select * into rec from public.receivables where sale_id=sale for update;if rec.id is null then return public.v2_reverse_sale_0014(sale,sh,n,d,op,approval,payload);end if;
 if not public.v2_has_permission(s.organization_id,'sales.reverse',s.branch_id)then raise exception using errcode='P0001',message='V2_SALE_REVERSE_REQUIRED';end if;a:=public.v2_current_membership_id(s.organization_id);c:=public.v2_use_approved_command(approval,s.organization_id,'sales.reverse',op,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;perform public.v2_require_open_sales_shift(s.organization_id,s.branch_id,s.register_id,sh,d,a);
 if exists(select 1 from public.sale_returns where original_sale_id=sale and status='posted'and reversal_of_id is null)then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_RETURN_EXISTS';end if;if exists(select 1 from public.sales_v2 where reversal_of_id=sale)or s.status='reversed'then raise exception using errcode='P0001',message='V2_SALE_ALREADY_REVERSED';end if;
 if rec.outstanding_amount<>rec.original_amount or exists(select 1 from public.debt_allocations x where x.receivable_id=rec.id and x.amount>0 and not exists(select 1 from public.debt_allocations z where z.reversal_of_id=x.id))then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_DEBT_ACTIVITY_EXISTS';end if;
 select jsonb_agg(jsonb_build_object('warehouse_id',s.warehouse_id,'product_id',z.product_id,'batch_id',z.batch_id)order by z.product_id,z.batch_id nulls first)into scopes from(select distinct sl.product_id,ba.product_batch_id batch_id from public.sale_lines_v2 sl join public.sale_line_batch_allocations ba on ba.sale_line_id=sl.id where sl.sale_id=sale union select distinct sl.product_id,null::uuid from public.sale_lines_v2 sl where sl.sale_id=sale)z;perform public.v2_lock_inventory_scopes(s.organization_id,scopes);
 perform set_config('market_pos.sales_command','on',true);perform set_config('market_pos.sale_reversal_command','on',true);perform set_config('market_pos.sale_build_command','on',true);perform set_config('market_pos.inventory_command','on',true);perform set_config('market_pos.debt_command','on',true);perform set_config('market_pos.settlement_command','on',true);
 insert into public.sales_v2(id,organization_id,branch_id,register_id,warehouse_id,shift_id,customer_counterparty_id,document_number,business_date,currency_code,subtotal_amount,discount_amount,tax_amount,total_amount,paid_amount,debt_amount,device_id,local_operation_id,client_created_at,posted_by,reversal_of_id)values(r,s.organization_id,s.branch_id,s.register_id,s.warehouse_id,sh,s.customer_counterparty_id,n,current_date,s.currency_code,s.subtotal_amount,s.discount_amount,0,s.total_amount,s.paid_amount,s.debt_amount,d,op,clock_timestamp(),a,sale);
 for l in select * from public.sale_lines_v2 where sale_id=sale order by line_number loop nl:=gen_random_uuid();insert into public.sale_lines_v2(id,organization_id,sale_id,line_number,product_id,product_name_snapshot,unit_id,unit_name_snapshot,product_price_id,quantity,unit_factor,base_quantity,unit_sale_price,unit_cost,discount_amount,tax_amount,line_total_amount)values(nl,l.organization_id,r,l.line_number,l.product_id,l.product_name_snapshot,l.unit_id,l.unit_name_snapshot,l.product_price_id,l.quantity,l.unit_factor,l.base_quantity,l.unit_sale_price,l.unit_cost,l.discount_amount,0,l.line_total_amount);for al in select * from public.sale_line_batch_allocations where sale_line_id=l.id loop na:=gen_random_uuid();mv:=gen_random_uuid();insert into public.sale_line_batch_allocations(id,organization_id,sale_line_id,product_batch_id,quantity,unit_cost,inventory_movement_id)values(na,s.organization_id,nl,al.product_batch_id,al.quantity,al.unit_cost,mv);insert into public.inventory_movements(id,organization_id,branch_id,warehouse_id,product_id,batch_id,movement_type,quantity_delta,source_document_type,source_document_id,source_line_id,movement_role,reversal_of_id,command_id,created_by)values(mv,s.organization_id,s.branch_id,s.warehouse_id,l.product_id,al.product_batch_id,'sale_reversal',al.quantity,'sale',r,na,'reversal',al.inventory_movement_id,c,a);update public.inventory_balances set on_hand_quantity=on_hand_quantity+al.quantity,last_movement_id=mv,version=version+1 where warehouse_id=s.warehouse_id and product_id=l.product_id and(batch_id=al.product_batch_id or batch_id is null);end loop;end loop;
 for pay in select p0.* from public.payments_v2 p0 where p0.sale_id=sale and p0.reversal_of_id is null loop np:=gen_random_uuid();insert into public.payments_v2(id,organization_id,branch_id,register_id,shift_id,sale_id,method,amount,currency_code,device_id,local_operation_id,reversal_of_id,created_by)values(np,s.organization_id,s.branch_id,s.register_id,sh,r,pay.method,-pay.amount,pay.currency_code,d,gen_random_uuid(),pay.id,a);update public.shift_totals set expected_amount=expected_amount-pay.amount,version=version+1,updated_at=now()where shift_id=sh and payment_method=pay.method;perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'payment',np,'payment.reversed','PaymentRefunded',jsonb_build_object('reversal_of_id',pay.id,'sale_id',r));end loop;
 da:=gen_random_uuid();insert into public.debt_allocations(id,organization_id,receivable_id,sale_reversal_id,allocation_type,amount,command_id,approval_request_id,created_by)values(da,s.organization_id,rec.id,r,'sale_reversal',rec.original_amount,c,approval,a);perform public.v2_recompute_receivable(rec.id);select * into primary_entry from public.settlement_entries where source_document_type='sale'and source_document_id=sale and entry_type='sale_debt'and reversal_of_id is null;se:=gen_random_uuid();insert into public.settlement_entries(id,organization_id,branch_id,counterparty_id,entry_type,amount_delta,currency_code,business_date,source_document_type,source_document_id,reversal_of_id,command_id,approval_request_id,created_by)values(se,s.organization_id,s.branch_id,rec.counterparty_id,'sale_debt',-primary_entry.amount_delta,rec.currency_code,current_date,'sale',r,primary_entry.id,c,approval,a);
 perform set_config('market_pos.sale_lifecycle_command','on',true);update public.sales_v2 set status='reversed'where id=sale;perform set_config('market_pos.sale_lifecycle_command','off',true);perform public.v2_create_fiscal_intent(s.organization_id,s.branch_id,s.register_id,sh,r,null,op::text,c,a);perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'receivable',rec.id,'receivable.reversed','ReceivableReversed',jsonb_build_object('receivable_id',rec.id,'sale_id',sale,'reversal_id',r));perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'settlement_entry',se,'settlement.entry.reversed','SettlementEntryReversed',jsonb_build_object('settlement_entry_id',se,'reversal_of_id',primary_entry.id));perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'sale',r,'sale.reversed','SaleReversed',jsonb_build_object('original_id',sale,'reversal_id',r));perform public.v2_complete_inventory_command(c,'sale',r,jsonb_build_object('id',r,'status','posted'));perform set_config('market_pos.settlement_command','off',true);perform set_config('market_pos.debt_command','off',true);perform set_config('market_pos.inventory_command','off',true);perform set_config('market_pos.sale_build_command','off',true);perform set_config('market_pos.sale_reversal_command','off',true);perform set_config('market_pos.sales_command','off',true);return r;end$$;
revoke execute on function public.v2_reverse_sale_0014(uuid,uuid,text,uuid,uuid,uuid,jsonb)from public,anon,authenticated;revoke execute on function public.v2_reverse_sale(uuid,uuid,text,uuid,uuid,uuid,jsonb)from public,anon;grant execute on function public.v2_reverse_sale(uuid,uuid,text,uuid,uuid,uuid,jsonb)to authenticated;
